const callBeforeWorkflow=callCapability;
callCapability=function(id,params={},failure='正常',fixture){
  if(ruleDemoContracts.some(c=>c.id===id)){
    const c=ability(id),sys=c&&connector(c.connector),base={capability:id,connector:c?.connector,params:structuredClone(params),revision:c?.revision,at:now()};
    if(!c||!sys||!sys.enabled)return {...base,ok:false,error:'系统连接或查询不可用，未能取得数据'};
    if(failure==='超时')return {...base,ok:false,error:'模拟接口超时，未能取得数据；提交阻断'};
    for(const [key,label]of c.params)if(params[key]===undefined||params[key]===null||params[key]==='')return {...base,ok:false,error:`缺少参数 ${label}（${key}），未能取得数据`};
    const authority=fixture||demoAuthority('all-pass');let raw;
    if(id==='demo.productDocuments')raw=authority.products[params.modelCode];
    if(id==='demo.safetyDI')raw=authority.projects[params.projectCode];
    if(id==='demo.minimumSystem')raw=authority.minimumSystems[`${params.projectCode}|${params.softwareCode}|${params.version}`];
    if(!raw)return {...base,ok:false,error:'权威样例中不存在该身份/版本的记录，未能取得数据'};
    return {...base,raw:structuredClone(raw),...normalizeCapabilityOutput(c,raw)};
  }
  // 为已有 PIS 模拟器补充明确登记的商品目录属性，不生成真实网络请求。
  if(['pis.getMaterial','pis.searchMaterials'].includes(id)){
    const c=ability(id),extra=c?.maps.filter(m=>m.target==='Material.inCatalog')||[];
    if(extra.length){const saved=c.maps;c.maps=saved.filter(m=>!extra.includes(m));let r;try{r=callBeforeWorkflow(id,params,failure)}finally{c.maps=saved}
      if(r.raw){const rows=r.raw.items||[r.raw];rows.forEach(row=>{row.IN_CATALOG=catalog.find(m=>m.materialCode===row.MATERIAL_CODE)?.inCatalog});r={...r,...normalizeCapabilityOutput(c,r.raw)};if(r.ok)delete r.error;}return r;}
  }
  return callBeforeWorkflow(id,params,failure);
};
const blockObjects={main:'ReleaseOrder',items:'ReleaseItem',modules:'ModuleOrder',mapping:'Mapping'};
const blockTables={main:'PRODUCT_RELEASE_ORDER',items:'RELEASE_ITEM',modules:'MODULE_ORDER',mapping:'RELEASE_MAPPING'};
function workflowScene(s){
  if(s.workflow)return s.workflow;
  const kind=sceneKind(s),blocks={};
  for(const [key,label]of Object.entries(s.names)){
    const prefix=scenePrefix(s,key),many=prefix.includes('[]'),path=prefix.replace(/\[\]\.$|\.$/,'');
    const object=kind==='release'?blockObjects[key]:key==='main'?s.root:kind==='range'?'RangeItem':'TrialItem';
    const fields=s.bindings[key].map(b=>{const [oid,pid]=b.ontology.split('.'),type=obj(oid)?.props.find(p=>p.id===pid)?.type;return {key:b.target.split('.').at(-1),label:b.label,type:['数字','布尔','日期'].includes(type)?type:'文本'}});
    const keyField=key==='main'?'id':key==='modules'?'moduleOrderId':'id';
    if(!fields.some(f=>f.key===keyField))fields.unshift({key:keyField,label:many?'业务行 ID':'单据 ID',type:'文本'});
    if(key==='main'&&!fields.some(f=>f.key==='submitDepartment'))fields.push({key:'submitDepartment',label:'提交业务部门',type:'文本'});
    blocks[key]={id:key,label,path,many,object,keyField,parent:key==='main'?'': 'main',table:kind==='release'?blockTables[key]:(key==='main'?'DEMO_ORDER':'DEMO_ITEM'),fields};
    for(const b of s.bindings[key]){b.sinkTable=blocks[key].table;b.sinkColumn=b.target.split('.').at(-1);}
  }
  s.workflow={type:'draft',blocks,instanceSource:'system',qa:{objects:['Material'],fields:['Material.materialCode','Material.materialName','Material.modelCode'],knowledge:'产品发布管理规范、产品资料维护指引',citation:'必须展示来源与记录编号'},rules:[],action:'研发发布提交'};
  if(kind==='release')s.workflow.rules=releaseRuleTemplates();
  return s.workflow;
}
