function workflowSettingsEditor(){const s=scene(),w=workflowScene(s),v=state.drawer.draft;return frame('数据怎么使用','选择数据从哪里来，以及在当前业务中怎样使用。',`<div class="form-grid">${field('应用场景类型 *','sceneType',v.sceneType,'select',sceneTypes)}${field('物料数据从哪里来（默认） *','instanceSource',v.instanceSource,'select',[['system','从业务系统查询'],['manual','用户手动创建']])}${v.instanceSource==='system'?field('哪些记录可以选择','candidate',v.candidate,'select',capabilities.filter(c=>c.object==='Material'&&!c.params.some(p=>p[0]==='materialCode')).map(c=>[c.id,c.name]))+field('对象资料默认从哪里查询','master',v.master,'select',capabilities.filter(c=>c.object==='Material'&&c.params.some(p=>p[0]==='materialCode')).map(c=>[c.id,c.name])):`<div class="wide">${inf('手工来源仅可复用当前会话中已有的记录；本体对象详情暂不提供手工记录管理入口。来源切换不会把手工数据写回 PIS。')}</div>`}${field('默认项目（测试时可改）','projectCode',v.projectCode)}${field('BOM 版本','bomVersion',v.bomVersion,'select',['B2','B3'])}${field('发布区域','region',v.region)}${field('业务日期','effectiveDate',v.effectiveDate,'date')}${v.sceneType==='qa'?field('可查询本体对象 *','qaObjects',v.qaObjects,'text',[],'使用英文对象英文代号，逗号分隔',true)+field('可检索属性 *','qaFields',v.qaFields,'textarea',[],'例如 Material.materialCode,Material.materialName；必须属于所选对象',true)+field('知识范围 *','knowledge',v.knowledge,'textarea',[],'知识库/文档范围，原型仅使用本地解释样例',true)+field('回答必须展示证据','citation',v.citation,'select',['必须展示来源与记录编号'],null,true):`<div class="wide">${inf(v.sceneType==='draft'?'智能提单：每条本体对象属性对应关系必须配置表单/API 目标字段、业务系统保存到哪张表、数据库字段。实际保存由业务系统完成。':'业务校验：使用业务记录、查询校验数据和检查要求，可不配置提单落库对应关系。')}</div>`}</div>`,btn('保存数据怎么用','workflow-save-settings','primary','check'),true)};
function workflowBlockEditor(){const d=state.drawer,b=d.draft,w=workflowScene(scene());return frame(d.isNew?'添加表单区块':'编辑表单区块','先设置主单和明细有哪些字段，再设置怎么填、怎么检查。',`<div class="form-grid">${field('区块名称 *','label',b.label)}${field('区块英文代号 *','id',b.id)}${field('字段组英文名称 *','path',b.path,'text',[],'例如 releaseItems，列表标记由下方这一块是一条还是多条记录决定')}${field('这一块是一条还是多条记录','cardinality',b.cardinality,'select',[['many','明细列表（逐行）'],['one','单条记录']])}${field('关联本体对象 *','object',b.object,'select',objects.map(o=>[o.id,o.name]))}${field('用哪个字段区分每条记录 *','keyField',b.keyField)}${field('所属区块','parent',b.parent,'select',[['','无（主单）'],...Object.values(w.blocks).filter(x=>x.id!==b.id).map(x=>[x.id,x.label])])}${field('业务系统保存的表名（样例）','table',b.table)}${field('业务字段清单 *','fieldsText',b.fieldsText,'textarea',[],'每行：英文标识 | 中文名称 | 文本/数字/布尔/日期。字段先在这里登记，再选择绑定。',true)}</div><div class="section-gap">${inf('已有绑定时，路径和这一块是一条还是多条记录保持稳定。删除字段前先解除字段绑定与规则参数引用。')}</div>`,btn('保存表单结构','workflow-save-block','primary','check'),true)};
sceneBindingEditor=function(){const d=state.drawer,b=d.draft,s=scene(),w=workflowScene(s),block=w.blocks[s.selectedBlock];return frame(d.index<0?'添加表单填入规则':'编辑表单填入规则',`${s.name} / ${block.label}`,`<div class="form-grid">${field('本体对象属性 *','ontology',b.ontology,'select',objects.flatMap(o=>o.props.map(p=>[`${o.id}.${p.id}`,`${o.name} / ${p.name}`])),null,true)}${field('这个属性的值从哪里来','instanceMode',b.instanceMode||'scene','select',[['scene','从本体对象的数据来源查询'],['manual','已创建的手工记录'],['input','当前表单用户输入']],null,true)}${workflowBindingSourcesField(s,b)}${b.instanceMode==='manual'?field('选择手工记录 *','instanceIdentity',b.instanceIdentity||'','select',[['','请选择'],...(manualInstances[b.ontology.split('.')[0]]||[]).map(m=>[m.identity,m.identity])],null,true):''}${field('填入哪个表单字段 *','target',b.target,'select',[['','请选择已设置的字段'],...block.fields.filter(f=>!f.mappingMode||f.mappingMode==='mapping').map(f=>[`${scenePrefix(s,block.id)}${f.key}`,`${typeof sceneMappingColumn==='function'?sceneMappingColumn(s,block,f).column:f.key} · ${f.label}`])],null,true)}${field('字段名称 *','label',b.label)}${field('填入表单的方式','direction',b.direction,'select',[['建议写入','用户确认后填入'],['双向','读取并回填'],['只读','只用于查看'],['引用绑定','关联对应记录']])}${field('业务系统保存的表名 *','sinkTable',b.sinkTable||block.table)}${field('数据库字段 *','sinkColumn',b.sinkColumn||'','text',[],'仅用于演示业务持久化对应关系，不执行数据库写入')}</div><div class="section-gap">${inf('目标字段必须先在“对象与表单映射”的“管理表单区块与字段”中登记。选择取数来源后，按上方设置的方式填入表单。')}</div><div class="row section-gap">${btn('测试填入结果','test-scene-binding','sm','play')}</div>${d.tested?`<div class="section-gap">${jsonView({source:b.ontology,target:b.target,persistence:{table:b.sinkTable,column:b.sinkColumn},selectedSources:workflowBindingSourceIds(s,b),sample:workflowBindingSample(s,b)})}</div>`:''}`,btn('保存填入规则','save-scene-binding','primary','check'),true)};
const workflowBindingValidator=validSceneBinding;
validSceneBinding=function(b,index){const old=workflowBindingValidator(b,index);if(old)return old;const sourceError=workflowBindingSourcesError(scene(),b);if(sourceError)return sourceError;if(b.instanceMode==='manual'&&!(manualInstances[b.ontology.split('.')[0]]||[]).some(m=>m.identity===b.instanceIdentity))return '请选择当前本体对象已创建的手工记录。';const s=scene(),w=workflowScene(s),block=w.blocks[s.selectedBlock];if(!block.fields.some(f=>scenePrefix(s,block.id)+f.key===b.target))return '请先在“对象与表单映射”的“管理表单区块与字段”中登记目标字段。';if(b.sinkColumn===undefined)b.sinkColumn=block.fields.find(f=>scenePrefix(s,block.id)+f.key===b.target)?.key;if(w.type==='draft'&&(!b.sinkTable?.trim()||!b.sinkColumn?.trim()))return '智能提单必须配置业务系统保存到哪张表和数据库字段。';return '';};
function ruleFacts(s,r){const w=workflowScene(s),b=w.blocks[r.scope];if(!b)return [];const main=Object.values(w.blocks).find(x=>!x.parent),facts=[];
 for(const f of b.fields)facts.push({id:`Row.${f.key}`,name:`当前行 · ${f.label}`,type:f.type,source:`row.${f.key}`});
 for(const f of main?.fields||[])facts.push({id:`Order.${f.key}`,name:`主单 · ${f.label}`,type:f.type,source:`order.${f.key}`});
 if(b.fields.some(f=>f.key==='materialCode'))facts.push({id:'Material.modelCode',name:'对应整机 · 产品型号',type:'文本',capability:s.master,output:'modelCode'},{id:'Material.inCatalog',name:'对应整机 · 是否为商品目录',type:'布尔',capability:s.master,output:'inCatalog'},...['documents','images','specifications','features'].map((key,i)=>({id:`Product.${key}`,name:['相关资料','产品图片','规格参数','功能特性'][i],type:'集合',capability:'demo.productDocuments',output:`product.${key}`})));
 if(!b.parent)facts.push({id:'Project.safetyDI',name:'当前项目 · 安全 DI',type:'数字',capability:'demo.safetyDI',output:'project.safetyDI'});
 if(b.fields.some(f=>f.key==='softwareCode'))facts.push({id:'Minimum.status',name:'当前软件版本 · 软管最小系统状态',type:'文本',capability:'demo.minimumSystem',output:'minimumSystem.status'});
 return facts;
}
function ruleFact(s,r,id){return ruleFacts(s,r).find(f=>f.id===id)}
const workflowOperators=[['eq','等于'],['neq','不等于'],['gt','大于'],['gte','大于等于'],['lt','小于'],['lte','小于等于'],['exists','存在且非空']];
function ruleText(s,r,a){return `${ruleFact(s,r,a.fact)?.name||a.fact} ${workflowOperators.find(o=>o[0]===a.op)?.[1]||a.op}${a.op==='exists'?'':` ${a.value==='true'?'是':a.value==='false'?'否':a.value}`}`;}
function workflowRulesView(s){const w=workflowScene(s);return `<div class="panel-body"><div class="between"><div><h3>校验规则</h3><p class="tiny muted section-gap">选择要检查的记录 → 判断是否需要检查 → 查询数据 → 逐项检查 → 说明不通过的原因</p></div>${btn('添加规则','workflow-add-rule','sm','plus')}</div><div class="section-gap">${inf('规则名称只用于说明；执行依赖下方设置的条件和检查要求。缺少检查数据、接口超时、身份不一致均按“未知”阻断，不能由 AI 猜测通过。')}</div>${w.rules.map((r,i)=>`<article class="workflow-rule section-gap"><div class="between"><div class="row"><span class="workflow-rule-num">${String(i+1).padStart(2,'0')}</span><h3>${esc(r.name)}</h3>${pill(r.enabled?r.level:'未启用',r.enabled?'blue':'')}</div><div class="row">${btn('配置','workflow-edit-rule','sm','edit',`data-id="${esc(r.id)}"`)}${btn('删除','workflow-delete-rule','sm danger','',`data-id="${esc(r.id)}"`)}</div></div><div class="workflow-rule-meta"><span>检查哪些记录：${esc(w.blocks[r.scope]?.label||'已失效')}</span><span>什么时候检查：${r.trigger==='submit'?'提交前终检':'保存草稿与提交前'}</span><span>范围：每条记录独立判断</span></div><dl class="kv"><dt>当</dt><dd>${r.conditions.length?r.conditions.map(a=>esc(ruleText(s,r,a))).join(' 且 '):'始终适用'}</dd><dt>必须满足</dt><dd>${r.assertions.map(a=>esc(ruleText(s,r,a))).join('；')}</dd><dt>检查数据从哪里来</dt><dd>${[...new Set([...r.conditions,...r.assertions].map(a=>ruleFact(s,r,a.fact)?.capability).filter(Boolean))].map(id=>esc(ability(id)?.name||id)).join('、')||'当前业务单据'}</dd><dt>不满足时</dt><dd>${esc(r.message)}</dd></dl></article>`).join('')||'<div class="empty">尚无规则，点击“添加规则”配置。</div>'}<div class="section-gap">${inf('可选范围、BOM 与认证仍执行已配置的基础校验。这里补充商品目录、安全 DI、最小系统等业务条件。')}</div></div>`;}
function workflowRuleEditor(){const s=scene(),d=state.drawer,r=d.draft,w=workflowScene(s),facts=ruleFacts(s,r),sourceOptions=[['','请选择参数值从哪里来'],...w.blocks[r.scope].fields.map(f=>[`row.${f.key}`,`当前行 · ${f.label}`]),...Object.values(w.blocks).find(b=>!b.parent).fields.map(f=>[`order.${f.key}`,`主单 · ${f.label}`]),['material.modelCode','当前行关联整机 · 产品型号']];
 const clauses=(type,label)=>`<div class="between section-gap"><h3>${label}</h3>${btn('添加一项','workflow-add-clause','sm','plus',`data-kind="${type}"`)}</div>${r[type].length?r[type].map((a,i)=>`<div class="workflow-clause"><select aria-label="${label}字段 ${i+1}" data-rule-clause="${type}" data-index="${i}" data-key="fact">${options([['','选择检查哪项数据'],...facts.map(f=>[f.id,`${f.name} · ${f.type}`])],a.fact)}</select><select aria-label="${label}运算 ${i+1}" data-rule-clause="${type}" data-index="${i}" data-key="op">${options(workflowOperators,a.op)}</select>${ruleFact(s,r,a.fact)?.type==='布尔'&&a.op!=='exists'?`<select aria-label="${label}比较值 ${i+1}" data-rule-clause="${type}" data-index="${i}" data-key="value">${options([['','请选择'],['true','是'],['false','否']],a.value)}</select>`:`<input aria-label="${label}比较值 ${i+1}" data-rule-clause="${type}" data-index="${i}" data-key="value" value="${esc(a.value)}" ${a.op==='exists'?'disabled placeholder="非空集合 / 非空值"':''}>`}<button class="link danger-text" data-action="workflow-remove-clause" data-kind="${type}" data-index="${i}">移除</button></div>`).join(''):'<p class="tiny muted section-gap">无前置条件，始终适用。</p>'}`;
 const ids=[...new Set([...r.conditions,...r.assertions].map(a=>ruleFact(s,r,a.fact)?.capability).filter(id=>id&&id!==s.master))];
 return frame(d.isNew?'添加校验规则':'配置校验规则','按记录编号取事实。所有条件为“且”，所有检查要求均满足才通过。',`<div class="form-grid">${field('规则名称 *','name',r.name,'text',[],null,true)}${field('执行对象 / 区块 *','scope',r.scope,'select',Object.values(w.blocks).map(b=>[b.id,b.label]))}${field('触发时机','trigger',r.trigger,'select',[['submit','提交前终检'],['save','保存草稿 + 提交前终检']])}${field('不满足时怎么处理','level',r.level,'select',[['阻断','不允许继续'],['警告','提醒，但允许继续']])}${field('是否启用','active',r.enabled?'启用':'停用','select',['启用','停用'])}</div>${clauses('conditions','什么情况下检查（每项都要满足）')}${clauses('assertions','要检查什么（每项都要满足）')}<hr class="divider"><h3>校验时要查询哪些数据</h3>${ids.map(id=>{const c=ability(id);return `<div class="inset-panel section-gap"><h3>${esc(c?.name||id)}</h3><code class="field-path">${esc(id)} · ${esc(c?.resource||'这项查询已删除')}</code><div class="form-grid section-gap">${(c?.params||[]).map(([key,label])=>`<div class="form-field"><label>${esc(label)} · ${esc(key)} *</label><select aria-label="参数 ${esc(key)}" data-rule-param="${esc(key)}">${options(sourceOptions,r.params[key]||'')}</select></div>`).join('')}</div><p class="tiny muted section-gap">${(c?.maps||[]).map(m=>`${esc(m.source)} → ${esc(m.target)}`).join('<br>')}</p></div>`}).join('')||'<p class="tiny muted section-gap">当前规则只使用业务表单字段或已关联的整机属性。</p>'}<div class="form-grid section-gap">${field('失败提示 *','message',r.message,'textarea',[],null,true)}</div><div class="section-gap">${inf('可增加“产品型号 等于 XX”条件，并与“是否为商品目录 等于 是”同时生效。软管最小系统按当前模块行的软件编码、版本和主单项目取数。')}</div>`,btn('确认并保存规则','workflow-save-rule','primary','check'),true);
}
function validateWorkflowRule(s,r){if(!r.name?.trim()||!r.message?.trim()||!r.assertions.length)return '请填写名称、失败提示并至少配置一个判断。';const w=workflowScene(s);if(!w.blocks[r.scope])return '执行对象不存在。';for(const a of [...r.conditions,...r.assertions]){const f=ruleFact(s,r,a.fact);if(!f||!workflowOperators.some(o=>o[0]===a.op))return '条件引用了当前执行对象不可用的字段或运算。';if(a.op!=='exists'&&!String(a.value).trim())return '请填写比较值。';if(['gt','gte','lt','lte'].includes(a.op)&&(f.type!=='数字'||!Number.isFinite(Number(a.value))))return '数值比较需要数字字段和合法数值。';if(f.type==='布尔'&&!['true','false'].includes(a.value))return '请选择“是”或“否”。';if(f.capability&&f.capability!==s.master){const c=ability(f.capability);if(!c)return '校验取数能力不存在。';for(const [key]of c.params){const source=r.params[key];if(!source)return `请绑定查询条件 ${key}。`;if(source==='material.modelCode'&&!w.blocks[r.scope].fields.some(f=>f.key==='materialCode'))return '当前区块没有关联整机物料。';const [origin,fieldKey]=source.split('.'),b=origin==='row'?w.blocks[r.scope]:Object.values(w.blocks).find(b=>!b.parent);if(origin!=='material'&&(!['row','order'].includes(origin)||!b.fields.some(f=>f.key===fieldKey)))return `参数 ${key} 引用的字段不存在。`;}}}return '';}
function demoAuthority(preset){const docs={documents:['资料.pdf'],images:['产品.png'],specifications:['规格参数'],features:['功能特性']};return {products:{'IPC-A400-EU':{...docs,images:preset==='missing-doc'?[]:docs.images},'IPC-B800-EU':structuredClone(docs)},projects:{'PRJ-2026-A':{safetyDI:preset==='di-positive'?2:0},'PRJ-2026-B':{safetyDI:0}},minimumSystems:{'PRJ-2026-A|SW-20260032|V5.8.2':{status:preset==='minimum-unreleased'?'未发布':'已发布'}}};}
function workflowDemoDocument(s,preset='all-pass'){const w=workflowScene(s),doc={};for(const b of Object.values(w.blocks)){const row={};for(const f of b.fields){const binding=s.bindings[b.id]?.find(x=>x.target===scenePrefix(s,b.id)+f.key);row[f.key]=binding?sceneValue(s,binding.ontology,catalog[0]):f.type==='数字'?1:f.type==='布尔'?false:'';}row[b.keyField]=b.fields.find(f=>f.key===b.keyField)?.type==='数字'?1:b.many?`${b.id.toUpperCase()}-001`:'REL-2026-0108';if(!b.parent){row.projectCode=s.context.projectCode;row.submitDepartment=preset==='other-department'?'前端业务部':'后端业务部';}if(b.fields.some(f=>f.key==='materialCode')&&(b.object||(s.bindings[b.id]||[]).some(m=>m.ontology==='Material.materialCode')))row.materialCode=preset==='out-of-range'?'MAT-20260099':'MAT-20260081';if(b.fields.some(f=>f.key==='softwareCode')&&(b.object||(s.bindings[b.id]||[]).some(m=>m.ontology==='Software.softwareCode')))Object.assign(row,{softwareCode:'SW-20260032',version:'V5.8.2'});doc[b.path]=b.many?[row]:row;}
 if(preset==='multiple-rows'){const b=Object.values(w.blocks).find(b=>b.fields.some(f=>f.key==='materialCode'));if(b?.many)doc[b.path].push({...doc[b.path][0],[b.keyField]:'RI-002',materialCode:'MAT-20260082'});}return doc;}
function workflowCompare(value,op,expected,type){if(value===undefined||value===null)return {unknown:true,pass:false};if(op==='exists')return {pass:Array.isArray(value)?value.length>0:String(value).trim().length>0};let target=expected;if(type==='数字'){if(typeof value!=='number'||!Number.isFinite(value))return {unknown:true,pass:false};target=Number(expected);}if(type==='布尔'){if(typeof value!=='boolean')return {unknown:true,pass:false};target=expected==='true';}return {pass:({eq:()=>value===target,neq:()=>value!==target,gt:()=>value>target,gte:()=>value>=target,lt:()=>value<target,lte:()=>value<=target}[op]||(()=>false))()};}
