 'workflow-save-settings':()=>{const d=state.drawer.draft,s=scene(),w=workflowScene(s);if(!d.projectCode.trim())return errorDrawer('请配置默认项目。');if(d.instanceSource==='system'&&(!ability(d.candidate)||!ability(d.master)))return errorDrawer('请选择有效的记录来源与可选物料查询。');if(d.sceneType==='qa'){const ids=d.qaObjects.split(',').map(x=>x.trim()).filter(Boolean),fields=d.qaFields.split(',').map(x=>x.trim()).filter(Boolean);if(!ids.length||ids.some(id=>!obj(id))||!fields.length||fields.some(path=>{const [oid,pid]=path.split('.');return !ids.includes(oid)||!obj(oid)?.props.some(p=>p.id===pid)})||!d.knowledge.trim())return errorDrawer('请配置有效的对象、属于该对象的检索属性及知识范围。');w.qa={objects:ids,fields,knowledge:d.knowledge,citation:d.citation};}w.type=d.sceneType;w.instanceSource=d.instanceSource;s.candidate=d.candidate;s.master=d.master;Object.assign(s.context,{projectCode:d.projectCode,bomVersion:d.bomVersion,region:d.region,effectiveDate:d.effectiveDate});workflowInvalidate();closeOverlay(true);render();toast('已保存应用类型与场景使用策略')},
