 'workflow-save-block':()=>{const d=state.drawer,v=d.draft,s=scene(),w=workflowScene(s),old=w.blocks[d.originalId];if(!/^[A-Za-z]\w*$/.test(v.id)||!v.label.trim()||!/^[A-Za-z]\w*$/.test(v.path)||!obj(v.object))return errorDrawer('请填写区块名称、合法英文标识、数据路径及本体对象。');if(d.isNew&&w.blocks[v.id]||Object.values(w.blocks).some(b=>b.id!==d.originalId&&b.path===v.path))return errorDrawer('区块标识或路径重复。');if(!d.isNew&&v.id!==d.originalId)return errorDrawer('区块标识被引用，请保持稳定。');let fields=v.fieldsText.split('\n').filter(x=>x.trim()).map(line=>{const [key,label,type]=line.split('|').map(x=>x.trim());return {...old?.fields.find(f=>f.key===key),key,label,type:type||'文本'}});if(!fields.length||fields.some(f=>!/^[A-Za-z]\w*$/.test(f.key)||!f.label||!['文本','数字','布尔','日期'].includes(f.type))||new Set(fields.map(f=>f.key)).size!==fields.length||!fields.some(f=>f.key===v.keyField))return errorDrawer('字段需使用唯一英文标识、中文名和合法类型，且必须包含记录唯一编号字段。');if((s.bindings[v.id]?.length||w.rules.some(r=>r.scope===v.id))&&old&&(old.path!==v.path||old.many!==(v.cardinality==='many')||old.object!==v.object||old.keyField!==v.keyField))return errorDrawer('区块已有绑定或规则引用，路径、对象、结构和唯一编号须保持稳定。');if(!v.parent&&Object.values(w.blocks).some(b=>!b.parent&&b.id!==v.id))return errorDrawer('场景只允许一个主单，其余区块请选择所属区块。');let parent=v.parent,visited=new Set([v.id]);while(parent){if(visited.has(parent))return errorDrawer('所属区块不能形成循环。');visited.add(parent);if(!w.blocks[parent])return errorDrawer('所属区块不存在。');parent=w.blocks[parent].parent;}if(!v.parent&&v.cardinality==='many')return errorDrawer('主单必须为单条记录。');const removed=old?.fields.filter(f=>!fields.some(n=>n.key===f.key))||[];for(const f of removed){if(s.bindings[v.id]?.some(b=>b.target===scenePrefix(s,v.id)+f.key)||w.rules.some(r=>[...r.conditions,...r.assertions].some(a=>a.fact===`Row.${f.key}`&&r.scope===v.id||a.fact===`Order.${f.key}`&&!old.parent)||Object.values(r.params).includes(`row.${f.key}`)&&r.scope===v.id||Object.values(r.params).includes(`order.${f.key}`)&&!old.parent))return errorDrawer(`字段 ${f.key} 被对应关系或规则引用，请先解除。`);}w.blocks[v.id]={id:v.id,label:v.label,path:v.path,many:v.cardinality==='many',object:v.object,keyField:v.keyField,parent:v.parent,table:v.table,fields};s.names[v.id]=v.label;s.bindings[v.id]??=[];s.selectedBlock=v.id;workflowInvalidate();closeOverlay(true);render();toast('表单结构已登记，字段现在可被场景对应关系选择')},
