 'workflow-save-manual':()=>{const d=state.drawer,o=obj(d.object),properties={},key=o.props.find(p=>p.key);if(!key)return errorDrawer('请先定义对象唯一编号。');for(const p of o.props){let v=d.draft[p.id];if((p.key||p.required)&&!String(v??'').trim())return errorDrawer(`请填写 ${p.name}。`);if(v===undefined||v==='')continue;if(p.type==='数字'){if(!Number.isFinite(Number(v)))return errorDrawer(`${p.name} 需要有效数字。`);v=Number(v);}if(p.type==='布尔'){if(!['true','false'].includes(v))return errorDrawer(`${p.name} 需要选择是或否。`);v=v==='true';}if(p.type==='日期'&&!/^\d{4}-\d{2}-\d{2}$/.test(v))return errorDrawer(`${p.name} 需要有效日期。`);properties[p.id]=v;}const id=properties[key.id],existing=(manualInstances[o.id]||[]).some(m=>m.properties[key.id]===id)||o.id==='Material'&&catalog.some(m=>m.materialCode===id)||capsForObject(o.id).length>0&&String(key.value)===String(id);if(existing)return errorDrawer('唯一编号已存在，请避免与系统或手工记录冲突。');manualInstances[o.id]??=[];manualInstances[o.id].push({identity:`${o.id}:${id}`,properties,source:'用户手动创建',at:now()});changed();Object.values(appScenes).forEach(s=>{if(s.workflow?.instanceSource==='manual'){s.revision++;s.lastResult=null;}});log('记录创建',`${o.name}:${id}`,'成功','来源：用户手动创建');closeOverlay(true);state.object=o.id;state.tab='props';render();toast('手工记录已创建，可在数据怎么用中选择手动来源')},
 'workflow-run-qa':()=>{const s=scene(),w=workflowScene(s),d=state.drawer,q=d.draft.question;if(!q.trim())return errorDrawer('请输入问题。');const records=w.qa.objects.flatMap(oid=>w.instanceSource==='manual'?(manualInstances[oid]||[]).map(m=>({...m,object:oid,source:'用户手动创建'})):oid==='Material'?catalog.map(m=>({identity:`Material:${m.materialCode}`,object:oid,properties:m,source:'PIS 本地样例'})):[]);const found=records.filter(m=>w.qa.fields.some(path=>{const [oid,key]=path.split('.'),value=m.properties[key];return oid===m.object&&value!==undefined&&String(value).trim()!==''&&q.includes(String(value))}));const evidence=found.map(m=>({identity:m.identity,source:m.source,properties:Object.fromEntries(w.qa.fields.filter(p=>p.startsWith(m.object+'.')).map(p=>[p,m.properties[p.split('.')[1]]]))}));d.result={found:!!found.length,answer:found.length?'在允许的对象与检索字段范围内找到以下记录。':'当前配置范围内没有匹配证据，无法回答；不会推测缺失信息。',evidence};drawOverlay()}
