configErrors=function(){const errors=workflowConfigErrors();for(const s of Object.values(appScenes)){const w=workflowScene(s);for(const [id,b]of Object.entries(w.blocks)){if((b.object||b.structureSource!=='table')&&!obj(b.object))errors.push(`${s.name} 的区块 ${b.label} 引用对象不存在`);if(!b.fields.some(f=>f.key===b.keyField))errors.push(`${s.name} 的区块 ${b.label} 未定义身份字段`);for(const m of s.bindings[id]||[]){if(!b.fields.some(f=>scenePrefix(s,id)+f.key===m.target))errors.push(`${s.name} 对应关系目标未登记：${m.target}`);if(w.type==='draft'&&(!m.sinkTable||!m.sinkColumn))errors.push(`${s.name} 智能提单缺少落库对应关系：${m.target}`);}}for(const r of w.rules){const error=validateWorkflowRule(s,r);if(error)errors.push(`${s.name} / ${r.name}：${error}`);}}return [...new Set(errors)];};
const workflowPropertyRefs=propertyDeleteReferences;
propertyDeleteReferences=function(o,p){const refs=workflowPropertyRefs(o,p),path=`${o.id}.${p.id}`;for(const s of Object.values(appScenes)){const w=workflowScene(s);for(const r of w.rules)if([...r.conditions,...r.assertions].some(a=>a.fact===path))refs.push(`场景“${s.name}”规则“${r.name}”使用此属性，请先修改规则。`);if(w.type==='qa'&&w.qa.fields.includes(path))refs.push(`场景“${s.name}”问答检索字段使用此属性，请先调整问答设置。`);}return refs;};
