// 建议写入使用当前业务行；明确展示来源，不把模拟建议当作已经落库。
function workflowSuggestions(s,doc){
 const w=workflowScene(s),payload=structuredClone(doc),suggestions=[],calls=[],cache=new Map();
 const query=(id,params)=>{const key=JSON.stringify([id,params]);if(cache.has(key))return cache.get(key);const r=callCapability(id,params);calls.push(r);cache.set(key,r);return r;};
 for(const b of Object.values(w.blocks)){
   const data=doc[b.path],rows=b.many?data:[data];if(!Array.isArray(rows))continue;
   rows.forEach((row,index)=>{if(!row)return;for(const binding of s.bindings[b.id]){
     const [oid,pid]=binding.ontology.split('.'),key=binding.target.split('.').at(-1);let value,source,sourceResult;
     if(binding.instanceMode==='manual'){
       const m=manualInstances[oid]?.find(m=>m.identity===binding.instanceIdentity);value=m?.properties[pid];source=m?`${m.identity} · 用户手动创建`:'手工记录不存在';
     }else if(binding.instanceMode==='input'){
       value=row[key];source='当前表单用户输入';
     }else if(Array.isArray(binding.sourceCapabilities)||workflowBindingSourceIds(s,binding).some(id=>ability(id)?.maps.some(m=>m.target===binding.ontology&&String(m.conditionValue??'').trim()))){
       const main=Object.values(w.blocks).find(b=>!b.parent);sourceResult=workflowBindingQueryValue(s,binding,row,doc[main.path]||{},query);value=sourceResult.value;source=sourceResult.source;
     }else if(oid==='Material'){
       if(w.instanceSource==='manual'){const m=manualInstances.Material?.find(m=>m.properties.materialCode===row.materialCode);value=m?.properties[pid];source=m?`${m.identity} · 用户手动创建`:'手工记录不存在';}
       else{const r=query(s.master,{materialCode:row.materialCode});value=r.ok?r.normalized?.find(x=>x.properties.materialCode===row.materialCode)?.properties[pid]:undefined;source=`${s.master} · ${row.materialCode||'缺少物料身份'}`;}
     }else if(oid==='Software'){
       const r=query('software.getPackage',{softwareCode:row.softwareCode});value=r.ok?r.normalized?.[0]?.properties[pid]:undefined;source=`software.getPackage · ${row.softwareCode||'缺少软件身份'}`;
     }else{value=row[key];source='当前业务记录输入 / 业务系统身份';}
     const hasCurrent=row[key]!==undefined&&row[key]!==null&&row[key]!=='';
     const preserve=hasCurrent&&['保留用户修改','差异确认','保持稳定引用'].includes(binding.policy);
     const changedValue=value!==undefined&&JSON.stringify(value)!==JSON.stringify(row[key]);
     const required=!!(binding.required||obj(oid)?.props.find(p=>p.id===pid)?.required||b.fields.find(f=>f.key===key)?.required);
     const status=sourceResult?.errors?.length?'来源查询失败':sourceResult?.conflict?'多个来源的值不一致，待确认':value===undefined&&sourceResult?.unmatched?.length?(required||hasCurrent?'未匹配取值条件，需处理':'未匹配取值条件（可留空）'):value===undefined?'来源缺失':preserve&&changedValue?'保留现值，待确认差异':'生成建议';
     const blocking=['来源查询失败','多个来源的值不一致，待确认','未匹配取值条件，需处理','来源缺失'].includes(status);
     if(!preserve&&value!==undefined){if(b.many)payload[b.path][index][key]=value;else payload[b.path][key]=value;}
     suggestions.push({target:`${b.path}[${row[b.keyField]}].${key}`,ontology:binding.ontology,source,...(sourceResult?{sourceValues:sourceResult.candidates,sourceErrors:sourceResult.errors||[],mappingEvidence:sourceResult.evaluations||[]}:{}),current:row[key],suggested:value===undefined?'未知':value,status,blocking,persistence:{table:binding.sinkTable,column:binding.sinkColumn}});
   }});
 }
 return {suggestions,payload,calls};
}
actionsMap['workflow-generate']=()=>{const d=state.drawer,s=scene();let doc;try{doc=JSON.parse(d.draft.documentText)}catch(e){return errorDrawer(`业务 JSON 不合法：${e.message}`)}const errors=workflowDocumentErrors(s,doc);if(errors.length)return errorDrawer(errors.join('；'));const generated=workflowSuggestions(s,doc);d.result={...generated,errors:[],checks:[],passed:generated.suggestions.every(s=>!s.blocking),revision:s.revision,event:'suggest',at:now()};d.submitted=false;d.error='';drawOverlay();};
