const workflowDeletionPlan=deletionPlan;
deletionPlan=function(kind,target,owner={}){
  const plan=workflowDeletionPlan(kind,target,owner);
  if(kind==='manualRecord'&&plan.exists){
    for(const s of Object.values(appScenes))for(const [block,bindings]of Object.entries(s.bindings)){
      for(const b of bindings)if(b.instanceMode==='manual'&&b.ontology.startsWith(owner.object+'.')&&b.instanceIdentity===target.identity)plan.refs.push(`场景“${s.name} / ${s.names[block]||block}”的“${b.label}”使用此记录，请先修改或删除该字段绑定。`);
    }
    const key=obj(owner.object)?.props.find(p=>p.key),id=target.properties[key?.id];
    for(const [oid,records]of Object.entries(manualInstances))for(const record of records){
      if(record===target)continue;
      for(const p of obj(oid)?.props||[]){
        const value=record.properties[p.id];
        if((p.type==='引用'||p.ref)&&value!==undefined&&(String(value)===target.identity||p.ref===owner.object&&String(value)===String(id)))plan.refs.push(`手工记录“${record.identity}”的“${p.name}”引用此记录，请先解除引用。`);
      }
    }
  }
  if(kind==='object'&&target){
    for(const s of Object.values(appScenes)){const w=workflowScene(s);if(Object.values(w.blocks).some(b=>b.object===target.id))plan.refs.push(`场景“${s.name}”的表单区块引用此对象，请先调整表单结构。`);if(w.type==='qa'&&w.qa.objects.includes(target.id))plan.refs.push(`场景“${s.name}”的问答范围引用此对象。`);}
    if(manualInstances[target.id]?.length)plan.refs.push('此对象存在手工记录，当前暂不能删除对象。');
  }
  plan.refs=[...new Set(plan.refs)];return plan;
};
