actionsMap['add-scene-binding']=()=>{const s=scene(),b=workflowScene(s).blocks[s.selectedBlock];openDrawer('sceneBinding',{label:'',target:'',ontology:'Material.materialCode',direction:'建议写入',policy:'差异确认',sinkTable:b.table,instanceMode:'scene',sourceCapabilities:[]},{index:-1});};
const workflowEditBindingBeforeSources=actionsMap['edit-scene-binding'];
actionsMap['edit-scene-binding']=function(el){const result=workflowEditBindingBeforeSources(el),d=state.drawer;if(d?.type==='sceneBinding'&&!['manual','input'].includes(d.draft.instanceMode)){d.draft.sourceCapabilities=workflowBindingSourceIds(scene(),d.draft);drawOverlay();}return result;};
function workflowBindingSample(s,b){const [oid,pid]=b.ontology.split('.');if(!['manual','input'].includes(b.instanceMode)&&Array.isArray(b.sourceCapabilities)){const row={...catalog[0],softwareCode:'SW-20260032'},r=workflowBindingQueryValue(s,b,row,s.context,(id,params)=>callCapability(id,params));return {value:r.value??'未知',valuesFromSources:r.candidates,conflict:r.conflict,errors:r.errors||[]};}if(b.instanceMode==='manual')return manualInstances[oid]?.find(m=>m.identity===b.instanceIdentity)?.properties[pid]??'实例属性为空';return sceneValue(s,b.ontology,catalog[0]);}
